import '../utilities/constants.dart';
import '../utilities/flutter_secure_storage_interface.dart';
import '../utilities/logger.dart';
import '../utilities/prefs.dart';
import 'hive/db.dart';

class DbVersionMigrator {
  // Stack Wallet's older steps (v1..v15) only converted data of other coins
  // and of old Stack Wallet releases, none of which a PIVXie install has.
  // A fresh install still needs the defaults the early steps used to set.
  Future<void> migrate(
    int fromVersion, {
    required SecureStorageInterface secureStore,
  }) async {
    Logging.instance.i("Running migrate fromVersion $fromVersion");
    if (fromVersion >= Constants.currentDataVersion) {
      return;
    }

    if (fromVersion < 3) {
      await DB.instance.hive.openBox<dynamic>(DB.boxNamePrefs);
      final prefs = Prefs.instance;
      await prefs.init();
      if (!(await prefs.isExternalCallsSet())) {
        prefs.externalCalls = true;
      }
    }

    await DB.instance.put<dynamic>(
      boxName: DB.boxNameDBInfo,
      key: "hive_data_version",
      value: Constants.currentDataVersion,
    );
  }
}
